def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    mode = 'probe'
    early_def = False
    if n >= 1:
        for i in range(min(n, 4)):
            if history[i][1] == 'D':
                early_def = True
                break
    if early_def:
        mode = 'retaliatory'
    elif n >= 5 and history[4][1] == 'D':
        mode = 'retaliatory'
    elif n >= 7 and history[6][1] == 'D':
        mode = 'threshold'
    elif n >= 9 and history[8][1] == 'D':
        mode = 'threshold'
    elif n >= 9:
        mode = 'forgiving'
    if mode == 'probe':
        if n == 1:
            return 'C'
        if n == 2:
            return 'C'
        if n == 3:
            return 'D'
        if n == 4:
            return 'C'
        if n == 5:
            return 'D'
        if n == 6:
            return 'C'
        if n == 7:
            return 'D'
        if n == 8:
            return 'C'
        return 'C'
    elif mode == 'retaliatory':
        if n >= 99:
            return 'D'
        if n >= 96:
            for i in range(95, n):
                if history[i][1] == 'D':
                    return 'D'
        if history[-1][1] == 'D':
            if rng.random() < 0.9:
                return 'D'
            else:
                return 'C'
        return 'C'
    elif mode == 'threshold':
        if n < 20:
            return 'C'
        if n == 99:
            return 'D'
        if (n - 20) % 6 == 0:
            return 'D'
        return 'C'
    else:
        return 'D'
